enum Department {
    CSE, ISE, ECE, MECH
}

Department d = Department.CSE;

String input = "CSE";
Department d = Department.valueOf(input);
System.out.println(d);

switch (d) {
case CSE -> System.out.println("Computer Science");
case ISE -> System.out.println("Information Science");
default -> System.out.println("Other branch");
}

