class Box<T> {
    private T value;
    Box(T value) { this.value = value; }
    T get() { return value; }
}

Box<Integer> b = new Box<>(10);

class Pair<K, V> {
    K key;
    V value;
    Pair(K k, V v) {
        key = k; value = v;
    }
}

